    "category": "Política",
    "ingestedAt": "16/11/2026 às 18:11",
    "imageUrl": "https://imagens.ebc.com.br/tdh93-z3YuS95N7-LW-LxyzoptA=/1170x700/smart/https://agenciabrasil.ebc.com.br/sites/default/files/thumbnails/image/2026/08/12/sem_titulo.jpg?itok=4Ls8Tr7o",
