    "source": "Agência Brasil",
    "sourceUrl": "https://agenciabrasil.ebc.com.br",
    "articleUrl": "https://agenciabrasil.ebc.com.br/geral/noticia/2026-11/operacao-fronteira-apreende-r-581-mi-em-produtos-ilegais-e-drogas",
    "publishedAt": "16/11/2026 às 14:55",
    "category": "Política",
    "ingestedAt": "16/11/2026 às 16:19",
    "imageUrl": "https://imagens.ebc.com.br/rw9MGOTBjHXOUt0lm1TWF1-5xnI=/1170x700/smart/https://agenciabrasil.ebc.com.br/sites/default/files/thumbnails/image/2026/11/16/pzzb0665.jpg?itok=XmsHiAva",
    "imageCaption": "Operação Fronteira apreende R$ 581 mi em produtos ilegais e drogas",
